// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts Every account on this instance
	// (GET /accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request)
	// CreateAccount Make an account for a person
	// (POST /accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request)
	// DeactivateAccount Stop an account from signing in
	// (DELETE /accounts/{accountId})
	DeactivateAccount(w http.ResponseWriter, r *http.Request, accountId string)
	// SetAccountRole Promote or demote an account
	// (PATCH /accounts/{accountId})
	SetAccountRole(w http.ResponseWriter, r *http.Request, accountId string)
	// GetHealth Report whether the service is able to serve
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// WhoAmI Who this request resolves to
	// (GET /me)
	WhoAmI(w http.ResponseWriter, r *http.Request)
	// ListProjects The projects this caller may see
	// (GET /projects)
	ListProjects(w http.ResponseWriter, r *http.Request)
	// CreateProject Open a book
	// (POST /projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// GetProject Read a project
	// (GET /projects/{slug})
	GetProject(w http.ResponseWriter, r *http.Request, slug string)
	// ListAxes Read the project's rendering axes, in their declared order
	// (GET /projects/{slug}/axes)
	ListAxes(w http.ResponseWriter, r *http.Request, slug string)
	// OrderAxes Declare the order the axes read in
	// (PUT /projects/{slug}/axes)
	OrderAxes(w http.ResponseWriter, r *http.Request, slug string)
	// HeadBlob Report whether the store already holds this content
	// (HEAD /projects/{slug}/blobs/{hash})
	HeadBlob(w http.ResponseWriter, r *http.Request, slug string, hash string)
	// PutBlob Store content under its address
	// (PUT /projects/{slug}/blobs/{hash})
	PutBlob(w http.ResponseWriter, r *http.Request, slug string, hash string)
	// GetCaptureImage The image a capture holds
	// (GET /projects/{slug}/captures/{captureId})
	GetCaptureImage(w http.ResponseWriter, r *http.Request, slug string, captureId string)
	// ListCases List the catalogue
	// (GET /projects/{slug}/cases)
	ListCases(w http.ResponseWriter, r *http.Request, slug string, params ListCasesParams)
	// CreateCase Open a case and receive its id
	// (POST /projects/{slug}/cases)
	CreateCase(w http.ResponseWriter, r *http.Request, slug string)
	// GetCase Read a case, archived or not
	// (GET /projects/{slug}/cases/{caseId})
	GetCase(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// UpdateCase Change what is mutable about a case
	// (PATCH /projects/{slug}/cases/{caseId})
	UpdateCase(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// ArchiveCase Take a case out of the catalogue
	// (POST /projects/{slug}/cases/{caseId}/archive)
	ArchiveCase(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// GetCaseCaptures Read the evidence a case is judged from
	// (GET /projects/{slug}/cases/{caseId}/captures)
	GetCaseCaptures(w http.ResponseWriter, r *http.Request, slug string, caseId string, params GetCaseCapturesParams)
	// ListComments Read what has been said about a case
	// (GET /projects/{slug}/cases/{caseId}/comments)
	ListComments(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// ReleaseCase Let the case go
	// (DELETE /projects/{slug}/cases/{caseId}/lock)
	ReleaseCase(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// ClaimCase Hold the case, or keep holding it
	// (POST /projects/{slug}/cases/{caseId}/lock)
	ClaimCase(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// SaveReview Save what one review session decided
	// (POST /projects/{slug}/cases/{caseId}/reviews)
	SaveReview(w http.ResponseWriter, r *http.Request, slug string, caseId string)
	// ListCategories Read the catalogue tree
	// (GET /projects/{slug}/categories)
	ListCategories(w http.ResponseWriter, r *http.Request, slug string)
	// CreateCategory Add a node to the tree
	// (POST /projects/{slug}/categories)
	CreateCategory(w http.ResponseWriter, r *http.Request, slug string)
	// DeleteCategory Remove an empty node
	// (DELETE /projects/{slug}/categories/{categoryId})
	DeleteCategory(w http.ResponseWriter, r *http.Request, slug string, categoryId string)
	// UpdateCategory Rename or move a node
	// (PATCH /projects/{slug}/categories/{categoryId})
	UpdateCategory(w http.ResponseWriter, r *http.Request, slug string, categoryId string)
	// EditComment Edit a draft remark
	// (PATCH /projects/{slug}/comments/{commentId})
	EditComment(w http.ResponseWriter, r *http.Request, slug Slug, commentId CommentId)
	// DeliverComment Ask for a judgment on a delivered fix
	// (POST /projects/{slug}/comments/{commentId}/delivery)
	DeliverComment(w http.ResponseWriter, r *http.Request, slug Slug, commentId CommentId)
	// DiscardComment Set a comment aside
	// (POST /projects/{slug}/comments/{commentId}/discard)
	DiscardComment(w http.ResponseWriter, r *http.Request, slug Slug, commentId CommentId)
	// UnjudgeComment Take a judgment back
	// (DELETE /projects/{slug}/comments/{commentId}/judgment)
	UnjudgeComment(w http.ResponseWriter, r *http.Request, slug Slug, commentId CommentId)
	// JudgeComment Accept a delivery, or refuse it
	// (POST /projects/{slug}/comments/{commentId}/judgment)
	JudgeComment(w http.ResponseWriter, r *http.Request, slug Slug, commentId CommentId)
	// TrackComment Attach an external issue to a comment
	// (POST /projects/{slug}/comments/{commentId}/reference)
	TrackComment(w http.ResponseWriter, r *http.Request, slug Slug, commentId CommentId)
	// CreateEdition Take a run's evidence into the book
	// (POST /projects/{slug}/editions)
	CreateEdition(w http.ResponseWriter, r *http.Request, slug string)
	// ListMembers Who reaches this project
	// (GET /projects/{slug}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, slug string)
	// RevokeMembership Take a person off a project
	// (DELETE /projects/{slug}/members/{accountId})
	RevokeMembership(w http.ResponseWriter, r *http.Request, slug string, accountId string)
	// GrantMembership Put a person on a project, or change what they may do
	// (PUT /projects/{slug}/members/{accountId})
	GrantMembership(w http.ResponseWriter, r *http.Request, slug string, accountId string)
	// GetReviewQueue Read the captures awaiting the reviewer
	// (GET /projects/{slug}/queue)
	GetReviewQueue(w http.ResponseWriter, r *http.Request, slug string, params GetReviewQueueParams)
	// GetRecordingVideo The video a recording holds
	// (GET /projects/{slug}/recordings/{recordingId})
	GetRecordingVideo(w http.ResponseWriter, r *http.Request, slug string, recordingId string)
	// UnjudgeRecording Take the recording's verdict back
	// (DELETE /projects/{slug}/recordings/{recordingId}/judgment)
	UnjudgeRecording(w http.ResponseWriter, r *http.Request, slug string, recordingId string)
	// JudgeRecording Render a verdict on the recording on screen
	// (POST /projects/{slug}/recordings/{recordingId}/judgment)
	JudgeRecording(w http.ResponseWriter, r *http.Request, slug string, recordingId string)
	// CreateServiceAccount Make a program an account on this project
	// (POST /projects/{slug}/service-accounts)
	CreateServiceAccount(w http.ResponseWriter, r *http.Request, slug string)
	// DeactivateServiceAccount Retire a program
	// (DELETE /projects/{slug}/service-accounts/{serviceAccountId})
	DeactivateServiceAccount(w http.ResponseWriter, r *http.Request, slug string, serviceAccountId string)
	// ListServiceTokens What tokens this program holds
	// (GET /projects/{slug}/service-accounts/{serviceAccountId}/tokens)
	ListServiceTokens(w http.ResponseWriter, r *http.Request, slug string, serviceAccountId string)
	// MintServiceToken Mint another token for this program
	// (POST /projects/{slug}/service-accounts/{serviceAccountId}/tokens)
	MintServiceToken(w http.ResponseWriter, r *http.Request, slug string, serviceAccountId string)
	// RetireServiceToken Stop one token working
	// (DELETE /projects/{slug}/service-accounts/{serviceAccountId}/tokens/{tokenId})
	RetireServiceToken(w http.ResponseWriter, r *http.Request, slug string, serviceAccountId string, tokenId string)
	// RequestSignIn Ask for a sign-in link
	// (POST /sign-in)
	RequestSignIn(w http.ResponseWriter, r *http.Request)
	// ClaimSignIn Spend a sign-in link and open a session
	// (POST /sign-in/claim)
	ClaimSignIn(w http.ResponseWriter, r *http.Request)
	// SignOut End this session
	// (POST /sign-out)
	SignOut(w http.ResponseWriter, r *http.Request)
	// WhoIsTheToken What a token can learn about itself
	// (GET /token)
	WhoIsTheToken(w http.ResponseWriter, r *http.Request)
}

